export const CYME_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/cyme-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getCymeStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(CYME_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
